1	#!/usr/bin/env bun
2	/**
3	 * resolve_resume_agent.ts — Decide which agent `/resume` means.
4	 *
5	 * `/resume` is `/<agent>` with the name filled in from what actually ran here, so a
6	 * person who wants to continue does not have to remember whether it was the engineer
7	 * or the reviewer. That is the only thing it does differently, which is why it takes
8	 * no instruction: `/<agent>` already resumes the same session AND carries one.
9	 *
10	 * The name is read from the thread rather than stored anywhere, the same choice
11	 * `dispatch-chain.ts` makes about handoffs. Every result comment already carries
12	 * `AGENT_TAG` -- `post_result_comment.ts` writes it so a later run can recognise its
13	 * own past output -- so the most recent one is the answer, and there is nothing extra
14	 * to keep in sync.
15	 *
16	 * Writes `agent` to $GITHUB_OUTPUT, empty when there is nothing to resume.
17	 *
18	 * Usage:
19	 *   resolve_resume_agent.ts --number N
20	 */
21	import { appendFileSync } from "node:fs";
22	import { parseArgs } from "node:util";
23	import { gh } from "../lib/gh.ts";
24	import { AGENT_TAG, LLM_CONTEXT_TAG } from "../lib/tags.ts";
25	import { defineScript } from "./lib/script-ref.ts";
26	
27	export interface ResolveResumeAgentArgs {
28	  number: string | number;
29	}
30	
31	export const ref = defineScript<ResolveResumeAgentArgs>(import.meta.url);
32	
33	/**
34	 * The agent named by the most recent comment that names one.
35	 *
36	 * Newest first, because an issue worked by an orchestrator and then an engineer must
37	 * resume the engineer. Taking the first match in chronological order would resume
38	 * whoever went first, every time, for the whole life of the issue.
39	 */
40	export function mostRecentAgent(bodies: string[]): string {
41	  for (let i = bodies.length - 1; i >= 0; i--) {
42	    const agent = AGENT_TAG.read(bodies[i] ?? "");
43	    if (agent) return agent;
44	  }
45	  return "";
46	}
47	
48	function main(): void {
49	  const { values } = parseArgs({ args: Bun.argv.slice(2), options: { number: { type: "string" } } });
50	  if (!values.number) {
51	    console.error("usage: resolve_resume_agent.ts --number N");
52	    process.exit(2);
53	  }
54	
55	  const repo = process.env.GITHUB_REPOSITORY ?? "";
56	  const { code, stdout, stderr } = gh(
57	    "api", `repos/${repo}/issues/${values.number}/comments`, "--paginate", "--jq", "[.[].body]",
58	  );
59	
60	  let agent = "";
61	  if (code === 0) {
62	    try {
63	      agent = mostRecentAgent(JSON.parse(stdout || "[]") as string[]);
64	    } catch {
65	      agent = "";
66	    }
67	  } else {
68	    console.error(`Could not read comments on #${values.number}: ${stderr || stdout}`);
69	  }
