1	/**
2	 * reusable-workflow.ts — Type-safe calling convention for `workflow_call`
3	 * reusable workflows defined by another `*.wac.ts` file in this project
4	 * (i.e. `atomaton-runner.wac.ts`, called from `atomaton-entry.wac.ts`,
5	 * `atoma-auto-trigger.wac.ts`, `atomaton-manual-comment.wac.ts`, and
6	 * `atoma-pr-review.wac.ts`).
7	 *
8	 * The upstream `ReusableWorkflowCallJob` (from `@github-actions-workflow-ts`)
9	 * takes a bare `uses: string` path and an untyped `with: {[k: string]: ...}`
10	 * object -- nothing connects a call site to the actual `workflow_call.inputs`
11	 * declared by the target workflow. Renaming/removing/typo'ing an input, or
12	 * renaming the target workflow's output filename, is a silent runtime break
13	 * (a bad `with:` key is just dropped by GitHub Actions), not a compile error.
14	 *
15	 * `defineCallableWorkflow` closes that gap: given the target `Workflow`
16	 * instance and an input type `TInputs` (written once, mirroring the
17	 * workflow's own `workflow_call.inputs`), it returns a `.call()` factory
18	 * that:
19	 *   - derives `uses:` from the target workflow's own `.filename`, so the
20	 *     path can never drift from the actual generated file name.
21	 *   - type-checks `with:` against `TInputs` at every call site (typo'd,
22	 *     missing-required, or removed inputs become compile errors).
23	 */
24	import { ReusableWorkflowCallJob, type NormalJob, type Workflow } from "@github-actions-workflow-ts/lib";
25	import type { GeneratedWorkflowTypes as GWT } from "@github-actions-workflow-ts/lib";
26	
27	type JobRef = NormalJob | ReusableWorkflowCallJob;
28	
29	export interface CallableWorkflowOptions<TInputs extends object> {
30	  /** Jobs this call depends on (becomes the job's `needs:`). */
31	  needs: JobRef[];
32	  /** Bare (non-`${{ }}`-wrapped) `if:` condition gating this call. */
33	  if?: string;
34	  /** Inputs passed to the reusable workflow, type-checked against `TInputs`. */
35	  with: TInputs;
36	  /** Secrets forwarded to the reusable workflow. Omit to pass none. */
37	  secrets?: "inherit" | Record<string, string>;
38	}
39	
40	export interface CallableWorkflow<TInputs extends object> {
41	  /** Build a `ReusableWorkflowCallJob` invoking this workflow, `with:` checked against `TInputs`. */
42	  call(jobName: string, options: CallableWorkflowOptions<TInputs>): ReusableWorkflowCallJob;
43	}
44	
45	export function defineCallableWorkflow<TInputs extends object>(workflow: Workflow): CallableWorkflow<TInputs> {
46	  const filename = workflow.filename;
47	  if (!filename) {
48	    throw new Error("defineCallableWorkflow: target workflow has no filename to derive `uses:` from");
49	  }
50	  const uses = `./.github/workflows/${filename}.yml`;
51	
52	  return {
53	    call(jobName, options) {
54	      return new ReusableWorkflowCallJob(jobName, {
55	        ...(options.if !== undefined ? { if: options.if } : {}),
56	        uses,
57	        with: options.with as unknown as GWT.ReusableWorkflowCallJob["with"],
58	        ...(options.secrets !== undefined ? { secrets: options.secrets } : {}),
59	      }).needs(options.needs);
60	    },
61	  };
62	}

