{"content": "#!/usr/bin/env bun
/**
 * resolve_pr_branch.ts — which branch a `pr` run is working on, if any.
 *
 * A `pr` run checks the pull request out through `refs/pull/N/head`, which git
 * checks out DETACHED: the commit is the pull request's, the ref is not a branch,
 * and `git rev-parse --abbrev-ref HEAD` answers `HEAD`. So the run had no branch
 * to push to, and `commit_and_push` died on
 *
 *     fatal: invalid refspec '(HEAD detached at pull/802/head)'
 *
 * — the one agent whose job is to push a fix onto a red pull request was the one
 * that could not. This script names the branch the pull request is already from;
 * the workflow step beside it materialises that branch at the commit the run
 * already has.
 *
 * The counterpart of `resolve_issue_branch.ts`, and best-effort in the same way:
 * it never fails the run it is deciding for. An empty `branch` output means there
 * is no branch to name, the run stays on the detached checkout, and the tool that
 * needs a branch refuses with a message saying what the run cannot do. Stopping
 * before the agent has said anything would be worse than that.
 *
 * Usage:
 *   resolve_pr_branch.ts --repo owner/name --number 12
 *
 * Writes `branch=<name-or-empty>` to $GITHUB_OUTPUT.
 */
import { appendFileSync } from "node:fs";
import { parseArgs } from "node:util";
import { gh, gitRun } from "../lib/gh.ts";
import { defineScript } from "./lib/script-ref.ts";

export interface ResolvePrBranchArgs {
  repo: string;
  number: string;
}

export const ref = defineScript<ResolvePrBranchArgs>(import.meta.url);

function log(message: string): void {
  console.error(`[atomaton-pr-branch] ${message}`);
}

/** What `gh pr view` was asked for, and what a malformed answer means. */
export interface PrHead {
  branch: string;
  /** True when the head branch lives in a fork rather than in this repository. */
  crossRepository: boolean;
}

/**
 * Read the head branch out of `gh pr view --json headRefName,isCrossRepository`.
 *
 * Pure, and forgiving on purpose: this is one of the ways the run may end up with
 * no branch, and an answer that cannot be parsed is that case rather than an
 * exception. The fork flag is carried separately from the name because the two
 * refusals are different facts about the pull request, and a reader of the log
 * needs to be able to tell them apart.
 */
export function prHead(prJson: string): PrHead {
  try {
    const pr = JSON.parse(prJson) as { headRefName?: unknown; isCrossRepository?: unknown };
    return {
      branch: typeof pr.headRefName === "string" ? pr.headRefName.trim() : "",
      crossRepository: pr.isCrossRepository === true,
    };
  } catch {
    return { branch: "", crossRepository: false };
  }
}

/**
 * Whether a name may be used as a branch, asked of git rather than pattern-matched.
 *
 * `check-ref-format --branch` is the same rule `git checkout` and `git push`
 * apply, so a name it accepts cannot be one they refuse — and one it rejects
 * never reaches the shell that splices it into a fetch refspec or the
 * `$GITHUB_ENV` write that becomes `BRANCH`. That covers the empty name, `HEAD`
 * (not a branch, and exactly what the step this replaces used to write), names
 * carrying whitespace, control characters, `..`, `~`, `^`, `:`, `.lock`, and
 * anything starting with `-`.
 */
export function isBranchName(name: string): boolean {
  if (!name) return false;
  return gitRun("check-ref-format", "--branch", name).code === 0;
}

/**
 * Whether the branch is one `origin` has.
 *
 * A pull request's `headRefName` exists in its head repository, which for a fork
 * is not `origin`. Asking first turns "the fetch fails" into "this run stays
 * detached", and it is what stops a fork's branch being mistaken for a branch of
 * the same name in the base repository.
 */
export function existsOnOrigin(name: string): boolean {
  const { code, stdout } = gitRun("ls-remote", "--heads", "origin", `refs/heads/${name}`);
  return code === 0 && stdout.trim() !== "";
}

function main(): void {
  const { values } = parseArgs({
    args: Bun.argv.slice(2),
    options: { repo: { type: "string" }, number: { type: "string" } },
  });

  const repo = (values.repo ?? "").trim();
  const number = Number((values.number ?? "").trim());
  const githubOutput = process.env.GITHUB_OUTPUT;

  // Never exits non-zero. Every path below either writes a name or writes an
  // empty one, and says on stderr which of the two happened and why.
  let branch = "";
  if (!repo || !Number.isInteger(number) || number <= 0) {
    log("missing --repo or --number; this run has no branch to name");
  } else {
    const { code, stdout, stderr } = gh(
      "pr", "view", String(number), "--repo", repo,
      "--json", "headRefName,isCrossRepository",
    );
    if (code !== 0) {
      log(`could not read pull request #${number}: ${stderr || stdout}`);
    } else {
      const head = prHead(stdout);
      if (head.crossRepository) {
        log(`pull request #${number} is from a fork, so its head branch is not one this repository can push to`);
      } else if (!head.branch) {
        log(`pull request #${number} names no head branch`);
      } else if (!isBranchName(head.branch)) {
        log(`pull request #${number} names '${head.branch}', which is not a branch name`);
      } else if (!existsOnOrigin(head.branch)) {
        log(`'${head.branch}' does not exist on origin; staying on the detached checkout`);
      } else {
        branch = head.branch;
      }
    }
  }

  log(branch ? `the pull request's head branch is ${branch}` : "no head branch to materialise; staying detached");
  if (githubOutput) appendFileSync(githubOutput, `branch=${branch}\n`);
}

if (import.meta.main) main();
